(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-720":{scenario:{company:"Bệnh viện Đa khoa Thiên Phúc Lam Hồng",supervisor:{name:"Lương Minh Khôi",role:{vi:"Kỹ thuật viên trưởng khoa Chẩn đoán hình ảnh",en:"Chief Radiologic Technologist"}},ref_code:"CT-5518",title:{vi:"Đúng giao thức. Đúng liều. An toàn người bệnh.",en:"Right protocol. Right dose. Patient safety first."},brief:{vi:"Đây là tình huống đào tạo. Phiếu chỉ định CT-5518 (người bệnh hư cấu): nghi thuyên tắc phổi, cân nặng 70 kg, eGFR 48 mL/phút/1,73 m². Bản lập lịch nháp đang chọn giao thức chụp ngực thường quy có thuốc và bơm 100 mL thuốc cản quang 350 mgI/mL. Đối chiếu với hướng dẫn giao thức đã duyệt, sửa giao thức chụp và thể tích thuốc cản quang, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. Order CT-5518 (fictional patient): suspected pulmonary embolism, weight 70 kg, eGFR 48 mL/min/1.73 m². The draft schedule uses a routine contrast chest protocol with 100 mL of 350 mgI/mL contrast. Compare it with the approved protocol guide, correct the scan protocol and the contrast volume, then write an evidence-based report."},reference_title:{vi:"Hướng dẫn giao thức CT đã duyệt · CT-5518",en:"Approved CT protocol guide · CT-5518"},fields:[{id:"PROTOCOL",label:{vi:"Giao thức chụp",en:"Scan protocol"},initial:"CHEST-CE",expected:"CTPA",choices:["CHEST-NC","CHEST-CE","CTPA"],reference:"Bảng chọn giao thức theo chỉ định",hint:{vi:"Nghi thuyên tắc phổi cần pha động mạch phổi, kích hoạt bolus tại thân động mạch phổi, không phải pha tĩnh mạch thường quy.",en:"Suspected PE needs a pulmonary arterial phase triggered at the pulmonary trunk, not a routine venous phase."}},{id:"CONTRAST_ML",label:{vi:"Thể tích thuốc cản quang (mL)",en:"Contrast volume (mL)"},initial:"100",expected:"56",reference:"Bảng liều thuốc cản quang",ref_value:{vi:"Cân nặng 70 kg; eGFR 48 mL/phút/1,73 m²; thuốc 350 mgI/mL",en:"Weight 70 kg; eGFR 48 mL/min/1.73 m²; contrast 350 mgI/mL"},hint:{vi:"Tính theo cân nặng trước, so với mức trần, rồi mới áp dụng hệ số giảm theo chức năng thận.",en:"Dose by weight first, check the cap, then apply the renal function reduction."}}],sop32:{vi:"Thể tích thuốc cản quang iod 350 mgI/mL = cân nặng x 1,0 mL/kg, tối đa 80 mL; eGFR 30-59 giảm 20%; eGFR dưới 30 phải hội chẩn bác sĩ chẩn đoán hình ảnh trước khi tiêm (định mức mô phỏng).",en:"Iodinated contrast volume (350 mgI/mL) = weight x 1.0 mL/kg, capped at 80 mL; reduce by 20% if eGFR is 30-59; eGFR below 30 requires radiologist review before injection (training values)."},context:{label:"RIS / CT-5518",metrics:[{label:{vi:"Cân nặng",en:"Body weight"},value:"70 kg"},{label:{vi:"eGFR",en:"eGFR"},value:"48 mL/min/1.73 m²"},{label:{vi:"Nồng độ thuốc",en:"Contrast strength"},value:"350 mgI/mL"}]},crisis:{vi:"Bác sĩ lâm sàng gọi giục: “Hồ sơ cũ ghi người bệnh từng nổi mề đay sau tiêm thuốc cản quang nhưng không sao đâu, cứ bơm 100 mL như mọi lần, đừng gọi bác sĩ chẩn đoán hình ảnh cho mất thời gian.”",en:"The referring doctor calls: “The old record says the patient had hives after contrast, but it's fine. Just inject 100 mL as usual and don't waste time calling the radiologist.”"},options:{safe:{vi:"Chưa tiêm, báo ngay bác sĩ chẩn đoán hình ảnh trực để đánh giá tiền sử phản ứng và quyết định phương án, chuẩn bị sẵn bộ cấp cứu phản vệ và ghi hồ sơ.",en:"Hold the injection, inform the on-call radiologist to assess the prior reaction and decide the plan, keep the anaphylaxis kit ready and document everything."},shortcut:{vi:"Bơm 100 mL như bác sĩ lâm sàng yêu cầu, nếu có phản ứng thì xử trí sau.",en:"Inject 100 mL as the referring doctor asks and treat any reaction afterwards."},wait:{vi:"Hoãn ca chụp, không báo ai và chờ khoa lâm sàng tự liên hệ lại.",en:"Postpone the scan, tell no one and wait for the ward to call back."}},questions:{vi:["Vì sao bạn đổi giao thức chụp? Dữ liệu nào trong phiếu chỉ định chứng minh lựa chọn đó?","Trình bày cách tính thể tích thuốc cản quang và cách xử lý khi phát hiện tiền sử phản ứng với thuốc cản quang."],en:["Why did you change the scan protocol? Which data in the order supports your choice?","Explain how you calculated the contrast volume and how you handle a documented prior contrast reaction."]},hints:{vi:["Đọc lại chẩn đoán nghi ngờ trên phiếu chỉ định trước khi chọn giao thức trong bảng chọn.","Theo SOP mục 3.2: tính theo cân nặng, kiểm tra mức trần, rồi áp dụng hệ số theo eGFR.","Đọc lại SOP mục 4.2: tiền sử phản ứng thuốc cản quang phải được bác sĩ chẩn đoán hình ảnh đánh giá trước khi tiêm."],en:["Re-read the suspected diagnosis on the order before choosing from the protocol table.","Per SOP 3.2: dose by weight, check the cap, then apply the eGFR factor.","Re-read SOP 4.2: a prior contrast reaction must be assessed by the radiologist before injection."]}},learning:{summary:{vi:"Kỹ thuật viên chẩn đoán hình ảnh vận hành máy X-quang, CT, MRI và hệ thống số hóa hình ảnh để tạo ra hình ảnh có giá trị chẩn đoán cho bác sĩ. Công việc gồm xác minh người bệnh, chọn đúng giao thức theo chỉ định, định vị chính xác, kiểm soát liều bức xạ theo nguyên tắc ALARA, phối hợp tiêm thuốc cản quang an toàn và bảo đảm chất lượng hình ảnh trên PACS. Nghề đòi hỏi kỹ năng kỹ thuật vững, tư duy an toàn và giao tiếp tốt với người bệnh.",en:"A medical imaging technologist operates X-ray, CT, MRI and digital imaging systems to produce diagnostic-quality images for physicians. The work covers patient identification, choosing the right protocol for the indication, accurate positioning, keeping radiation dose ALARA, safe contrast administration with the team and image quality control on PACS. The role requires solid technical skills, a safety mindset and good communication with patients."},responsibilities:{vi:["Xác minh người bệnh bằng ít nhất hai thông tin nhận dạng và đối chiếu phiếu chỉ định trước mỗi lần chụp.","Chọn giao thức chụp phù hợp chỉ định lâm sàng, điều chỉnh thông số theo thể trạng người bệnh.","Sàng lọc chống chỉ định: thai kỳ, chức năng thận, tiền sử dị ứng thuốc cản quang, kim loại khi chụp MRI.","Thực hiện kiểm tra chất lượng hằng ngày, ghi nhận liều bức xạ và báo cáo trường hợp vượt mức tham chiếu.","Gửi hình lên PACS đúng chuẩn DICOM, ghi chú kỹ thuật và phối hợp với bác sĩ đọc kết quả."],en:["Identify each patient with at least two identifiers and match the order before every scan.","Choose the protocol that fits the clinical indication and adjust parameters to the patient's build.","Screen contraindications: pregnancy, renal function, prior contrast reactions and metal before MRI.","Run daily quality control, record radiation dose and report cases above reference levels.","Send images to PACS in DICOM format, add technical notes and coordinate with the reporting radiologist."]},competencies:[{name:{vi:"Lựa chọn giao thức",en:"Protocol selection"},desc:{vi:"Liên kết câu hỏi lâm sàng với pha chụp, vùng chụp và thời điểm tiêm thuốc phù hợp.",en:"Link the clinical question to the right phase, scan range and contrast timing."}},{name:{vi:"An toàn bức xạ",en:"Radiation protection"},desc:{vi:"Áp dụng biện minh, tối ưu hóa và giới hạn liều; theo dõi CTDIvol, DLP so với mức tham chiếu.",en:"Apply justification, optimisation and dose limits; track CTDIvol and DLP against reference levels."}},{name:{vi:"Quản lý thuốc cản quang",en:"Contrast management"},desc:{vi:"Tính liều theo cân nặng và chức năng thận, nhận biết sớm phản ứng và phối hợp cấp cứu.",en:"Dose by weight and renal function, recognise reactions early and support emergency care."}},{name:{vi:"Chất lượng hình ảnh",en:"Image quality"},desc:{vi:"Đánh giá nhiễu, độ tương phản, nhiễu ảnh do chuyển động và quyết định chụp bổ sung có kiểm soát.",en:"Assess noise, contrast and motion artefacts and decide on controlled repeat imaging."}},{name:{vi:"Giao tiếp & đạo đức",en:"Communication & ethics"},desc:{vi:"Giải thích cho người bệnh, tôn trọng quyền riêng tư và báo cáo ngay khi có nguy cơ an toàn.",en:"Explain procedures to patients, respect privacy and escalate any safety risk immediately."}}],knowledge:{vi:["Luật Khám bệnh, chữa bệnh số 15/2023/QH15 và quy định về phạm vi hoạt động chuyên môn của kỹ thuật viên.","Nguyên tắc an toàn bức xạ: biện minh, tối ưu hóa (ALARA), giới hạn liều; quy định hiện hành về an toàn bức xạ trong y tế.","Mức liều tham chiếu chẩn đoán (DRL), ý nghĩa của CTDIvol, DLP và cách theo dõi liều người bệnh.","Sàng lọc và xử trí phản ứng thuốc cản quang iod, gadolinium; nguy cơ tổn thương thận sau tiêm thuốc cản quang.","An toàn MRI: phân vùng an toàn, sàng lọc kim loại và thiết bị cấy ghép, nhãn MR Safe, MR Conditional, MR Unsafe."],en:["Law on Medical Examination and Treatment No. 15/2023/QH15 and rules on technologists' scope of practice.","Radiation protection principles: justification, optimisation (ALARA) and dose limits; current rules on radiation safety in healthcare.","Diagnostic reference levels (DRL), the meaning of CTDIvol and DLP, and patient dose tracking.","Screening and management of iodinated and gadolinium contrast reactions; risk of kidney injury after contrast.","MRI safety: safety zones, screening for metal and implants, MR Safe, MR Conditional and MR Unsafe labels."]},tools:["Máy CT đa dãy đầu thu","Bơm tiêm thuốc cản quang tự động","Hệ thống RIS/PACS","Phantom kiểm tra chất lượng","Bộ cấp cứu phản vệ"],kpis:{vi:["Tỷ lệ chụp lại do lỗi kỹ thuật (mục tiêu dưới 3%).","Tỷ lệ ca có liều vượt mức tham chiếu chẩn đoán được rà soát.","Thời gian từ chỉ định đến hoàn tất chụp cấp cứu.","Số sự cố an toàn thuốc cản quang và tỷ lệ được báo cáo, xử lý đúng quy trình."],en:["Repeat rate due to technical errors (target below 3%).","Share of studies above diagnostic reference levels that were reviewed.","Time from order to completed emergency scan.","Contrast safety incidents and the share reported and handled per procedure."]},day:[{time:"07:00",vi:"Khởi động máy CT, hiệu chuẩn không khí và chụp phantom kiểm tra chất lượng hằng ngày.",en:"Warm up the CT scanner, run air calibration and the daily phantom QC scan."},{time:"08:00",vi:"Rà soát danh sách chỉ định, sàng lọc chức năng thận và tiền sử dị ứng của ca có tiêm thuốc.",en:"Review the worklist and screen renal function and allergy history for contrast cases."},{time:"10:30",vi:"Thực hiện ca chụp cấp cứu, phối hợp điều dưỡng đặt đường truyền và theo dõi người bệnh.",en:"Perform emergency scans, work with nurses on IV access and patient monitoring."},{time:"14:00",vi:"Tái tạo hình ảnh, kiểm tra chất lượng và gửi lên PACS kèm ghi chú kỹ thuật.",en:"Reconstruct images, check quality and send them to PACS with technical notes."},{time:"16:30",vi:"Ghi nhận liều bức xạ, cập nhật sổ sự cố và bàn giao ca.",en:"Record radiation dose, update the incident log and hand over the shift."}],mistakes:{vi:["Chọn giao thức theo thói quen thay vì theo câu hỏi lâm sàng trên phiếu chỉ định.","Bơm liều thuốc cản quang chuẩn cho mọi người bệnh, bỏ qua cân nặng và chức năng thận.","Bỏ qua bước xác minh hai thông tin nhận dạng hoặc nhầm bên chụp khi đông người bệnh."],en:["Choosing a protocol out of habit instead of the clinical question on the order.","Giving every patient a standard contrast dose, ignoring weight and renal function.","Skipping two-identifier verification or scanning the wrong side when the list is busy."]},career:[{vi:"Kỹ thuật viên chẩn đoán hình ảnh",en:"Medical imaging technologist"},{vi:"Kỹ thuật viên chuyên sâu CT, MRI",en:"Senior CT and MRI technologist"},{vi:"Kỹ thuật viên trưởng khoa Chẩn đoán hình ảnh",en:"Chief radiologic technologist"},{vi:"Quản lý chất lượng và an toàn bức xạ khoa",en:"Imaging quality and radiation safety manager"}],glossary:[{term:"CTPA",vi:"Chụp CT động mạch phổi có tiêm thuốc cản quang, dùng để chẩn đoán thuyên tắc phổi.",en:"CT pulmonary angiography with contrast, used to diagnose pulmonary embolism."},{term:"CTDIvol",vi:"Chỉ số liều CT thể tích, phản ánh cường độ bức xạ trên mỗi lát cắt của một lần quét.",en:"Volume CT dose index, reflecting radiation output per slice for a scan."},{term:"DLP",vi:"Tích liều theo chiều dài, bằng CTDIvol nhân chiều dài vùng quét, đơn vị mGy.cm.",en:"Dose length product, equal to CTDIvol times scan length, in mGy.cm."},{term:"ALARA",vi:"Nguyên tắc giữ liều bức xạ thấp nhất có thể hợp lý mà vẫn đạt mục đích chẩn đoán.",en:"Principle of keeping radiation dose as low as reasonably achievable while meeting the diagnostic goal."},{term:"Bolus tracking",vi:"Kỹ thuật theo dõi đậm độ thuốc tại vùng quan tâm để tự động bắt đầu quét đúng pha.",en:"Technique that monitors contrast density in a region of interest to start the scan at the right phase."}],quiz:[{q:{vi:"Người bệnh 60 kg, eGFR 52. Theo SOP mô phỏng 1,0 mL/kg, tối đa 80 mL, giảm 20% khi eGFR 30-59, thể tích thuốc cản quang là bao nhiêu?",en:"A 60 kg patient has eGFR 52. Under the training SOP of 1.0 mL/kg, max 80 mL, minus 20% for eGFR 30-59, what is the contrast volume?"},options:{vi:["60 mL","80 mL","48 mL","52 mL"],en:["60 mL","80 mL","48 mL","52 mL"]},answer:2,explain:{vi:"60 kg x 1,0 mL/kg = 60 mL, dưới mức trần 80 mL; giảm 20% vì eGFR 52 nên còn 48 mL.",en:"60 kg x 1.0 mL/kg = 60 mL, below the 80 mL cap; minus 20% for eGFR 52 gives 48 mL."}},{q:{vi:"Người bệnh chuẩn bị chụp MRI khai có máy tạo nhịp nhưng không rõ loại. Bạn làm gì?",en:"A patient about to have MRI reports a pacemaker of unknown type. What do you do?"},options:{vi:["Dừng lại, xác minh loại thiết bị và báo bác sĩ trước khi cho vào phòng máy","Cho chụp nhanh với chuỗi xung ngắn","Đề nghị người bệnh tự tắt máy tạo nhịp","Chụp vì đa số máy tạo nhịp mới đều an toàn"],en:["Stop, verify the device type and inform the physician before entering the scanner room","Scan quickly with short sequences","Ask the patient to switch off the pacemaker","Scan because most new pacemakers are safe"]},answer:0,explain:{vi:"Thiết bị cấy ghép chưa xác định trạng thái MR phải được coi là không an toàn cho đến khi có xác minh và quyết định của bác sĩ.",en:"An implant of unknown MR status must be treated as unsafe until it is verified and a physician decides."}},{q:{vi:"Nguyên tắc ALARA trong chẩn đoán hình ảnh có nghĩa là gì?",en:"What does the ALARA principle mean in medical imaging?"},options:{vi:["Luôn dùng liều cao để ảnh đẹp nhất","Không bao giờ chụp lại","Chỉ áp dụng cho trẻ em","Giữ liều thấp nhất có thể hợp lý mà vẫn đủ chất lượng chẩn đoán"],en:["Always use high dose for the best image","Never repeat a scan","Apply it only to children","Keep dose as low as reasonably achievable while keeping diagnostic quality"]},answer:3,explain:{vi:"ALARA là tối ưu hóa: đủ chất lượng để chẩn đoán với liều thấp nhất hợp lý, áp dụng cho mọi người bệnh.",en:"ALARA means optimisation: enough diagnostic quality with the lowest reasonable dose, for every patient."}},{q:{vi:"Hàng chờ dài, trưởng ca bảo bỏ bước hỏi lại họ tên và ngày sinh để chụp nhanh hơn. Bạn chọn cách nào?",en:"The queue is long and the shift lead says to skip asking name and date of birth to go faster. What do you choose?"},options:{vi:["Bỏ bước xác minh cho kịp","Vẫn xác minh hai thông tin nhận dạng và báo trưởng ca về rủi ro nhầm người bệnh","Chỉ xác minh với người bệnh lớn tuổi","Nhờ người nhà tự đọc tên"],en:["Skip verification to save time","Keep two-identifier verification and tell the shift lead about the wrong-patient risk","Verify only elderly patients","Let relatives read the name out"]},answer:1,explain:{vi:"Xác minh hai thông tin nhận dạng là hàng rào chống nhầm người bệnh, không được bỏ qua vì áp lực thời gian.",en:"Two-identifier verification is the barrier against wrong-patient events and cannot be skipped under time pressure."}}],tools_en:["Multi-detector CT scanner","Automated contrast media injector","RIS/PACS system","Quality control phantom","Anaphylaxis emergency kit"]}}})})(window.KKR);
